#!/usr/bin/env node
/**
 * Aligns and signs the APK that Gradle just built (unsigned — the bubblewrap
 * template doesn't wire a signingConfig), using the keystore generated by
 * generate-twa.cjs. Must run after `./gradlew assembleRelease`.
 *
 * Env vars (same as generate-twa.cjs):
 *   ANDROID_HOME / ANDROID_SDK_ROOT, JAVA_HOME
 */

const fs = require('fs')
const path = require('path')
const { Config, JdkHelper, AndroidSdkTools, ConsoleLog } = require('@bubblewrap/core')

const ROOT = path.resolve(__dirname, '..', '..')
const ANDROID_DIR = path.join(ROOT, 'android')
const PROJECT_DIR = path.join(ANDROID_DIR, 'project')
const CREDS_PATH = path.join(ANDROID_DIR, 'keystore-credentials.json')

async function main() {
  const androidSdkPath = process.env.ANDROID_HOME || process.env.ANDROID_SDK_ROOT
  const jdkPath = process.env.JAVA_HOME
  if (!androidSdkPath || !jdkPath) {
    throw new Error('ANDROID_HOME (or ANDROID_SDK_ROOT) and JAVA_HOME must be set in the environment.')
  }

  const creds = JSON.parse(fs.readFileSync(CREDS_PATH, 'utf8'))

  const config = new Config(jdkPath, androidSdkPath)
  const jdkHelper = new JdkHelper(process, config)
  const log = new ConsoleLog('ravon')
  const sdkTools = await AndroidSdkTools.create(process, config, jdkHelper, log)

  if (!(await sdkTools.checkBuildTools())) {
    log.info('Installing Android build-tools...')
    await sdkTools.installBuildTools()
  }

  const unsignedApk = path.join(PROJECT_DIR, 'app', 'build', 'outputs', 'apk', 'release', 'app-release-unsigned.apk')
  if (!fs.existsSync(unsignedApk)) {
    throw new Error(`Unsigned APK not found at ${unsignedApk}. Did the Gradle build run?`)
  }

  const alignedApk = path.join(ANDROID_DIR, 'ravon-aligned.apk')
  const signedApk = path.join(ANDROID_DIR, 'ravon.apk')

  log.info('Aligning APK...')
  await sdkTools.zipalign(unsignedApk, alignedApk)

  log.info('Signing APK...')
  await sdkTools.apksigner(creds.keystorePath, creds.storePassword, creds.alias, creds.keyPassword, alignedApk, signedApk)

  fs.rmSync(alignedApk, { force: true })
  log.info(`Signed APK ready at ${signedApk}`)
}

main().catch((err) => {
  console.error(err)
  process.exit(1)
})
